        "title": "Attā",
        "excerpt":"Grammatical Analysis Attā: [m.] self; soul; ego; abiding core; essence. (Equivalent to Sanskrit Ātman). Orthodox Definition In orthodox Theravāda doctrine, Attā represents the supreme existential illusion. It is the false, deeply ingrained assumption that within the shifting phenomena of the mind and body, there exists a permanent, independent, controlling “I”,...","categories": ["doctrinalConcept"],
