        "title": "Aṭṭhakathā",
        "excerpt":"Grammatical Analysis Aṭṭhakathā: [f.] Commentary; explanation of meaning. Formed by attha (meaning, sense, purpose) + kathā (talk, speech, discourse). Orthodox Definition The Aṭṭhakathā constitutes the vast body of classical Theravāda commentaries. While the Tipiṭaka contains the words of the Buddha, the Aṭṭhakathā contains the orthodox Mahāvihāra interpretations of those words....","categories": ["historicalContext"],
