        "excerpt":"Grammatical Analysis Dhammapada: [nt.] The Path of Dhamma; The Verses of Truth. Formed by dhamma (truth, doctrine) + pada (path, footstep, line, verse). Orthodox Definition The Dhammapada is the second book of the Khuddaka Nikāya and is arguably the most famous, widely read, and translated Buddhist text in the world....","categories": ["historicalContext"],
