        "title": "Kamma-paccaya",
        "excerpt":"Verified Grammatical Analysis Kammapaccaya: [m.] Kamma condition; Action condition. Formed by kamma (volitional action) + paccaya (condition). Orthodox Definition Kamma-paccaya is the thirteenth of the 24 Conditions. It explains how volition (cetanā) exerts its organizing and generative power over reality. This condition operates in two distinct temporal ways: Conascent Kamma...","categories": ["patthana"],
