        "title": "Muñcitukāmyatāñāṇa",
        "excerpt":"Grammatical Analysis Muñcitukāmyatāñāṇa: [nt.] Knowledge of desire for deliverance. Formed by muñcitu (to be freed, to escape) + kāmyatā (desire, longing) + ñāṇa (knowledge). Orthodox Definition Arising directly from disenchantment, Muñcitukāmyatāñāṇa is the intense, overwhelming, and singular desire of the mind to escape from the entire network of conditioned existence....","categories": ["doctrinalConcept"],
